#!/usr/bin/env python3
"""Attila / Spider Engine: validate catalog and produce local Preview only."""
import json, pathlib, html, urllib.parse
root=pathlib.Path(__file__).resolve().parent
config=json.loads((root/"vinted-funnel.json").read_text(encoding="utf-8"))
profile=config.get("seller_profile_url")
if profile:
    parsed_profile=urllib.parse.urlsplit(profile)
    if parsed_profile.scheme!="https" or parsed_profile.hostname!="www.vinted.fr" or not parsed_profile.path.startswith("/member/") or parsed_profile.username or parsed_profile.password or parsed_profile.port:
        raise ValueError("Invalid seller profile URL")
profile_cta=('<nav class="profile-cta" aria-label="Accès à la boutique Vinted"><a href="'+html.escape(profile,quote=True)+'" rel="noopener noreferrer nofollow" target="_blank" data-outbound="seller-profile">Voir toutes les annonces sur Vinted</a></nav>') if profile else ""
cards=[]
seen=set()
for item in config["catalog"]:
    if item["id"] in seen: raise ValueError("Duplicate poster id")
    seen.add(item["id"])
    url=item["vinted_url"]
    title=html.escape(item["title"])
    if url:
        parsed=urllib.parse.urlsplit(url)
        if parsed.scheme!="https" or parsed.hostname not in {"vinted.fr","www.vinted.fr","vinted.com","www.vinted.com"} or parsed.username or parsed.password or parsed.port or not parsed.path.startswith("/items/"):
            raise ValueError("Unverified Vinted host: "+str(url))
        link=html.escape(url,quote=True)
        cards.append(f'<article class="art-card"><div class="art-mat" aria-hidden="true"><span>TOILE D’OR</span></div><div class="art-info"><p class="eyebrow">Collection privée</p><h2>{title}</h2><a href="{link}" rel="noopener noreferrer nofollow" target="_blank" data-poster="{html.escape(item["id"])}">Découvrir sur Vinted <span aria-hidden="true">↗</span></a></div></article>')
    else:
        cards.append(f'<article class="art-card"><div class="art-mat" aria-hidden="true"><span>TOILE D’OR</span></div><div class="art-info"><p class="eyebrow">Collection privée</p><h2>{title}</h2><p class="unavailable">Annonce à vérifier avant activation.</p></div></article>')
page='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="theme-color" content="#111718"><title>Toile d’Or — galerie privée | affiches de collection</title><meta name="description" content="Toile d’Or : galerie privée d’affiches de musique, de cinéma et de photographies. Découvrez la sélection sur Vinted."><style>
:root{color-scheme:dark;--ink:#111718;--ivory:#f2e9d9;--gold:#bca17b;--muted:#afa89a}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--ink);color:var(--ivory);font:16px/1.7 Georgia,'Times New Roman',serif}a{color:inherit}a:focus-visible{outline:3px solid var(--gold);outline-offset:5px}.skip-link{position:absolute;left:-9999px;top:0;background:var(--ivory);color:var(--ink);padding:.8rem}.skip-link:focus{left:1rem;top:1rem;z-index:10}.topbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.2rem max(5vw,1rem);border-bottom:1px solid #bca17b40}.wordmark{font-size:1.2rem;letter-spacing:.24em;text-transform:uppercase}.edition{font:11px/1.4 system-ui,sans-serif;letter-spacing:.18em;text-transform:uppercase;color:var(--gold)}header.hero{text-align:center;padding:clamp(4rem,12vw,9rem) 1rem 5rem;background:radial-gradient(ellipse at 50% 25%,#28302e 0%,#111718 68%)}.eyebrow{font:11px/1.5 system-ui,sans-serif;letter-spacing:.25em;text-transform:uppercase;color:var(--gold)}h1{font-size:clamp(3.5rem,10vw,8.5rem);font-weight:400;line-height:1.05;letter-spacing:-.045em;margin:1.2rem 0}.hero p:last-child{color:var(--muted);max-width:36rem;margin:auto;font-size:1.15rem}.profile-cta{text-align:center;padding:0 1rem 4rem}.profile-cta a,.art-info a{display:inline-block;text-decoration:none;border-bottom:1px solid var(--gold);padding:.65rem .1rem;color:var(--ivory);font:12px/1.5 system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase;min-height:44px}.profile-cta a:hover,.art-info a:hover{color:var(--gold)}.section-head{max-width:1200px;margin:auto;padding:0 1.5rem 1.4rem;display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #bca17b40}.section-head h2{font-size:clamp(1.7rem,4vw,2.7rem);font-weight:400;margin:0}.section-head span{font:11px system-ui,sans-serif;color:var(--gold);letter-spacing:.15em}main{max-width:1200px;margin:2rem auto 6rem;padding:0 1.5rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:2.5rem}.art-card{min-width:0}.art-mat{height:clamp(240px,32vw,360px);display:grid;place-items:center;background:linear-gradient(135deg,#242927,#181c1c);border:12px solid #282622;outline:1px solid #bca17b55;box-shadow:0 18px 40px #0007,inset 0 0 0 1px #bca17b45}.art-mat span{font-size:.85rem;letter-spacing:.3em;color:#bca17b88}.art-info{padding:1.2rem .15rem}.art-info h2{font-size:1.8rem;font-weight:400;margin:.25rem 0 .8rem}.unavailable{color:var(--muted);font:13px/1.6 system-ui,sans-serif}footer{border-top:1px solid #bca17b40;text-align:center;padding:3rem 1rem;color:var(--muted);font-size:.9rem}@media(max-width:600px){.topbar{padding:1rem}.edition{font-size:9px}.section-head{align-items:start;gap:1rem}.art-mat{height:300px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><a class="skip-link" href="#catalogue">Aller aux affiches</a><div class="topbar"><span class="wordmark">Toile d’Or</span><span class="edition">Galerie d’affiches · Édition privée</span></div><header class="hero"><p class="eyebrow">L’art de collectionner les histoires</p><h1>Toile d’Or</h1><p>Des images qui traversent le temps. Une sélection d’affiches de musique, de cinéma et de photographie.</p></header>'''+profile_cta+'''<div class="section-head"><h2>La collection</h2><span>SÉLECTION</span></div><main id="catalogue">'''+"".join(cards)+'''</main><footer>Toile d’Or · Aperçu privé. Disponibilité et achat exclusivement sur Vinted.</footer><script>document.querySelectorAll("a[data-poster]").forEach(a=>a.addEventListener("click",()=>{try{const k="attila_clicks_"+a.dataset.poster;sessionStorage.setItem(k,String(Number(sessionStorage.getItem(k)||0)+1))}catch(e){}}));</script></body></html>'''
out=root/"preview.html"
out.write_text(page,encoding="utf-8")
print(f"Preview generated: {out}, configured item URLs (format checked, not live verified): {sum(bool(x['vinted_url']) for x in config['catalog'])}")
